package com.sora.splineroads.client;
import com.sora.splineroads.*;import com.sora.splineroads.core.*;import com.sora.splineroads.world.*;import com.sora.splineroads.net.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.*;import net.minecraft.client.*;import net.minecraft.client.gui.screens.TitleScreen;import net.minecraft.core.*;import net.minecraft.world.level.*;import net.minecraftforge.api.distmarker.Dist;import net.minecraftforge.event.TickEvent;import net.minecraftforge.eventbus.api.SubscribeEvent;import net.minecraftforge.fml.common.Mod;
@Mod.EventBusSubscriber(modid=SplineRoads.ID,value=Dist.CLIENT)
public final class Third211Visual {
 static final Path OUT=Path.of("third211");static final UUID GROUP=UUID.fromString("c3ba2c13-3ca2-3977-9e62-80fbd51280c3");static boolean started,done;static int ticks,stage,ready;static long deadline;static CompletableFuture<?> pending;
 static void log(String s)throws Exception{System.out.println("SR211 THIRD "+s);Files.writeString(OUT.resolve("results.txt"),s+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);}
 static void next(int s){stage=s;ready=ticks+180;}
 static void shot(Minecraft mc,String s)throws Exception{try(var i=Screenshot.takeScreenshot(mc.getMainRenderTarget())){i.writeToFile(OUT.resolve(s+".png"));}log("SCREENSHOT "+s);}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent e){
  if(!"third".equals(System.getProperty("road.feedback211Resume"))||done||e.phase!=TickEvent.Phase.END)return;var mc=Minecraft.getInstance();ticks++;
  try{
   if(!started){if(!(mc.screen instanceof TitleScreen)||mc.getOverlay()!=null)return;started=true;Files.createDirectories(OUT);deadline=System.nanoTime()+1800_000_000_000L;mc.options.pauseOnLostFocus=false;mc.options.cloudStatus().set(CloudStatus.OFF);mc.options.renderDistance().set(12);mc.options.framerateLimit().set(60);mc.options.enableVsync().set(false);mc.options.guiScale().set(2);mc.resizeDisplay();mc.createWorldOpenFlows().loadLevel(mc.screen,"sr211-third");log("OPEN NEW REPORT COPY");return;}
   if(System.nanoTime()>deadline)throw new AssertionError("timeout stage="+stage);
   if(mc.level==null||mc.player==null||mc.getOverlay()!=null||ticks<ready)return;
   mc.mouseHandler.releaseMouse();mc.player.setDeltaMovement(0,0,0);mc.player.getAbilities().flying=true;mc.player.setNoGravity(true);
   if(stage==0){mc.setScreen(null);mc.options.hideGui=true;if(Files.exists(OUT.resolve("light-only"))){Feedback211Visual.camera(mc,715,81,74,733,56,77);next(2);ready=ticks+500;return;}Feedback211Visual.camera(mc,547,85,1347,571.57,56,1347.49);next(1);ready=ticks+500;return;}
   if(stage==1){shot(mc,"01-green-seam");if(!Files.exists(OUT.resolve("seam-rebuilt"))){pending=mc.getSingleplayerServer().submit(()->Third211Scenes.rebuildSeam(Feedback211Visual.player(mc).serverLevel()));next(10);return;}Feedback211Visual.camera(mc,715,81,74,733,56,77);next(2);ready=ticks+500;return;}
   if(stage==10){if(!pending.isDone())return;pending.join();Files.writeString(OUT.resolve("seam-rebuilt"),"PASS");log("SEAM EDIT PASS");next(1);ready=ticks+500;return;}
   if(stage==2){shot(mc,"02-infill");if(Files.exists(OUT.resolve("light-only"))){Third211LightChecks.run(mc);com.sora.splineroads.config.RoadClientConfig.SURFACE_BACKEND.set(com.sora.splineroads.config.RoadClientConfig.SurfaceBackend.TERRAIN);next(11);ready=ticks+600;return;}var s=new StringBuilder();int count=0;for(int x=680;x<755;x++)for(int z=30;z<115;z++)for(int y=53;y<58;y++){var p=new BlockPos(x,y,z);if(mc.level.getBlockEntity(p) instanceof RoadFillEntity f&&count++<32)s.append(p).append(" material=").append(f.fill()).append(" cap=").append(f.cap()).append(" edge=").append(f.edge().size()).append(" outline=").append(f.outline().size()).append(" sky=").append(mc.level.getBrightness(LightLayer.SKY,p)).append(" above=").append(mc.level.getBrightness(LightLayer.SKY,p.above())).append(" sealed=").append(mc.level.getBlockState(p)).append('\n');}Files.writeString(OUT.resolve("fill-cells.txt"),s);Feedback211Visual.camera(mc,337,100,1261,350,61,1200);next(3);ready=ticks+400;return;}
   if(stage==11){shot(mc,"06-infill-terrain");log("TERRAIN BACKEND "+RoadTerrainModels.status());done=true;mc.stop();return;}
   if(stage==3){shot(mc,"03-ramp-before-save");mc.options.hideGui=false;pending=mc.getSingleplayerServer().submit(()->{Third211Scenes.openSpui(Feedback211Visual.player(mc));});next(4);return;}
   if(stage==4){if(!pending.isDone())return;pending.join();if(!(mc.screen instanceof InterchangeScreen screen))return;var f=InterchangeScreen.class.getDeclaredField("save");f.setAccessible(true);var save=(net.minecraft.client.gui.components.Button)f.get(screen);if(!save.active)return;shot(mc,"04-editor-ready");save.onPress();log("PRESSED REAL SAVE BUTTON");next(5);return;}
   if(stage==5){if(mc.screen instanceof InterchangeScreen screen){var f=InterchangeScreen.class.getDeclaredField("pending");f.setAccessible(true);if(f.getBoolean(screen))return;var status=InterchangeScreen.class.getDeclaredField("status");status.setAccessible(true);log("SAVE RECEIPT "+status.get(screen));}else if(mc.screen!=null)throw new AssertionError("editor lost after save "+mc.screen);else log("SAVE RECEIPT editor closed normally");pending=mc.getSingleplayerServer().submit(()->{var d=RoadData.get(Feedback211Visual.player(mc).serverLevel());var ramps=d.index.roads.values().stream().filter(r->GROUP.equals(r.record.assembly())&&r.mesh.settings().style().ramp()).toList();if(ramps.size()!=4||ramps.stream().anyMatch(r->r.mesh.length()>250))throw new AssertionError("save did not update all ramps");return ramps.stream().map(r->r.record.id()+" length="+r.mesh.length()).toList();});next(6);return;}
   if(stage==6){if(!pending.isDone())return;log("WIRE/UI SAVE PASS "+pending.join());mc.setScreen(null);mc.options.hideGui=true;Feedback211Visual.camera(mc,337,100,1261,350,61,1200);next(7);ready=ticks+500;return;}
   if(stage==7){shot(mc,"05-ramp-after-save");log("THIRD NATIVE DONE");done=true;mc.stop();}
  }catch(Throwable f){done=true;f.printStackTrace();try{log("FAIL stage="+stage+" "+f);}catch(Exception ignored){}mc.stop();}
 }
}
